var o=[{title:`La posición básica de carrera`,text:`Corre erguido y relajado, con una ligera inclinación natural hacia delante de todo el cuerpo y los brazos balanceándose con soltura. Mantén los hombros sueltos y no estires mucho el pie hacia delante en cada paso. Tu zancada debería sentirse coordinada a la velocidad que elijas, sin forzarla a encajar en una plantilla fija.`},{title:`Cadencia y apoyo del pie`,text:`La cadencia es el número de pasos que das por minuto. A algunos corredores puede beneficiarles cambiarla un poco, pero ninguna regla dice que todos deban correr a 180 pasos por minuto. Las pisadas de talón, de mediopié y de antepié reparten las fuerzas de manera distinta, y la evidencia no respalda que todos los corredores sanos deban cambiar a un único patrón de aterrizaje.`},{title:`Intervalos de caminar y correr`,text:`Si estás empezando, podrías alternar un minuto de trote suave con dos minutos de caminata durante 15–20 minutos, además de un calentamiento y una vuelta a la calma. A lo largo de varias semanas, alarga las partes de trote. Progresa según el tiempo, la confianza y lo duro que se siente, y haz pausas caminando cuando quieras. La cantidad inicial adecuada depende de lo activo que hayas sido, de cómo lo asuma tu cuerpo y de la superficie, así que no hay un calendario fijo que todos deban seguir.`},{title:`Los sprints son una habilidad aparte`,text:`Las aceleraciones rápidas exigen mucho más a los músculos y los tendones. Desarrolla una forma física básica de carrera antes de hacer sprints a toda velocidad, y calienta más tiempo cuando añadas esfuerzos más rápidos. Detente si sientes un dolor agudo o un dolor que empeora. Elige un calzado y un recorrido que se ajusten a la superficie y a las condiciones, y si correr choca con tus límites de impacto o no tienes una ruta segura, haz acondicionamiento de bajo impacto.`}];var s=[{label:`Revisión sistemática: técnica de pisada y riesgo de lesión`,url:`https://pubmed.ncbi.nlm.nih.gov/34527750/`},{label:`Revisión sistemática de la cadencia de carrera y el riesgo de lesión`,url:`https://pubmed.ncbi.nlm.nih.gov/40964543/`},{label:`Recomendaciones de actividad física de los CDC para adultos`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var i={sections:o,sources:s};export{i as default,o as sections,s as sources};